-- ============================================================
-- MIND CONNECT - CARGA DE SERVICOS PUBLICOS DE SAUDE - SAO PAULO
-- CAPS: 107 registros do arquivo CAPS fornecido, filtrados por CODIGO_IBGE_MUNICIPIO 355030
-- UPA: 36 unidades CNES tipo 73, ativas, municipais, SUS, com nome contendo UPA
-- UBS: 483 unidades do arquivo de importacao UBS fornecido
-- Municipio IBGE: 355030 - SAO PAULO/SP
-- Insercoes idempotentes: evita duplicidade pelo CODIGO_CNES.
-- Nao exclui nem atualiza registros existentes.
-- Fonte principal: CNES - Ministerio da Saude.
-- ============================================================

SET DEFINE OFF;

-- ------------------------------------------------------------
-- CATEGORIAS: cria apenas as que ainda nao existem.
-- ------------------------------------------------------------


SELECT 'CAPS', 'Centro de Atencao Psicossocial e servicos de acolhimento psicossocial classificados na carga CAPS.' FROM DUAL
WHERE NOT EXISTS (
    SELECT 1 FROM GS_CATEGORIA_SERVICO
    WHERE UPPER(TRIM(NOME)) = 'CAPS'
);

SELECT 'UPA', 'Unidade de Pronto Atendimento da rede publica de urgencia e emergencia.' FROM DUAL
WHERE NOT EXISTS (
    SELECT 1 FROM GS_CATEGORIA_SERVICO
    WHERE UPPER(TRIM(NOME)) = 'UPA'
);

SELECT 'UBS', 'Unidade Basica de Saude da Atencao Primaria.' FROM DUAL
WHERE NOT EXISTS (
    SELECT 1 FROM GS_CATEGORIA_SERVICO
    WHERE UPPER(TRIM(NOME)) = 'UBS'
);


