-- ============================================================
-- UBS - 483 REGISTROS DA CAPITAL
-- ============================================================





































































































































































































































































































































































































































































































COMMIT;

-- CONFERENCIA POR CATEGORIA E MUNICIPIO
SELECT C.NOME AS CATEGORIA, COUNT(*) AS TOTAL
FROM GS_SERVICO_ACOLHIMENTO S
         JOIN GS_CATEGORIA_SERVICO C ON C.ID_CATEGORIA_SERVICO = S.ID_CATEGORIA_SERVICO
WHERE S.CODIGO_IBGE_MUNICIPIO = '355030'
  AND UPPER(TRIM(C.NOME)) IN ('CAPS', 'UPA', 'UBS')
GROUP BY C.NOME
ORDER BY C.NOME;
